export const PAGE_SIZES=[10,25,50] as const;
export type PageSize=(typeof PAGE_SIZES)[number];
export function PageSizeSelect({value,onChange}:{value:PageSize;onChange:(size:PageSize)=>void}){return <label>Wierszy na stronę<select value={value} onChange={event=>{const parsed=Number(event.currentTarget.value);const next=PAGE_SIZES.find(size=>size===parsed);if(next!==undefined)onChange(next);}}>{PAGE_SIZES.map(size=><option key={size} value={size}>{size}</option>)}</select></label>;}

import {useState} from "react";
export type Priority="LOW"|"MEDIUM"|"HIGH"|"CRITICAL";
export type Ticket=Readonly<{id:number;title:string;priority:Priority;createdAt:string;assignee:string|null;status:"OPEN"|"IN_PROGRESS"|"CLOSED"}>;
export type SortKey="id"|"title"|"priority"|"createdAt";
export type Direction="asc"|"desc";
export type SortState=Readonly<{key:SortKey;direction:Direction}>;
export const PRIORITY_RANK:Record<Priority,number>={LOW:0,MEDIUM:1,HIGH:2,CRITICAL:3};
type Comparator=(a:Ticket,b:Ticket)=>number;
const COMPARATORS:Record<SortKey,Comparator>={id:(a,b)=>a.id-b.id,title:(a,b)=>a.title.localeCompare(b.title,"pl"),priority:(a,b)=>PRIORITY_RANK[a.priority]-PRIORITY_RANK[b.priority],createdAt:(a,b)=>Date.parse(a.createdAt)-Date.parse(b.createdAt)};
export function sortTickets(tickets:readonly Ticket[],sort:SortState):Ticket[]{const sign=sort.direction==="asc"?1:-1;return tickets.toSorted((a,b)=>COMPARATORS[sort.key](a,b)*sign);}
export function nextSort(current:SortState,key:SortKey):SortState{return current.key===key?{key,direction:current.direction==="asc"?"desc":"asc"}:{key,direction:"asc"};}
export function compareNullableText(a:string|null,b:string|null,direction:Direction):number{if(a===null&&b===null)return 0;if(a===null)return 1;if(b===null)return -1;return a.localeCompare(b,"pl")*(direction==="asc"?1:-1);}
export function SortHeader({label,column,sort,onSort}:{label:string;column:SortKey;sort:SortState;onSort:(key:SortKey)=>void}){const active=sort.key===column;return <th scope="col" aria-sort={active?(sort.direction==="asc"?"ascending":"descending"):undefined}><button type="button" onClick={()=>onSort(column)}>{label} <span aria-hidden="true">{active?(sort.direction==="asc"?"▲":"▼"):"↕"}</span></button></th>;}
export type PageResult<T>={pageItems:T[];currentPage:number;pageCount:number;from:number;to:number};
export function paginate<T>(items:readonly T[],page:number,pageSize:number):PageResult<T>{if(!Number.isSafeInteger(page))throw new RangeError("Page musi być bezpieczną liczbą całkowitą");if(!Number.isSafeInteger(pageSize)||pageSize<=0)throw new RangeError("PageSize musi być dodatnią bezpieczną liczbą całkowitą");const pageCount=Math.max(1,Math.ceil(items.length/pageSize));const currentPage=Math.min(Math.max(1,page),pageCount);const start=(currentPage-1)*pageSize;return {pageItems:items.slice(start,start+pageSize),currentPage,pageCount,from:items.length===0?0:start+1,to:Math.min(start+pageSize,items.length)};}
export function Pager({page,pageCount,onPageChange}:{page:number;pageCount:number;onPageChange:(page:number)=>void}){return <nav aria-label="Paginacja"><button type="button" disabled={page<=1} onClick={()=>{if(page>1)onPageChange(page-1);}}>Poprzednia</button>{Array.from({length:pageCount},(_,index)=>index+1).map(number=><button key={number} type="button" aria-label={`Strona ${number}`} aria-current={number===page?"page":undefined} onClick={()=>onPageChange(number)}>{number}</button>)}<button type="button" disabled={page>=pageCount} onClick={()=>{if(page<pageCount)onPageChange(page+1);}}>Następna</button></nav>;}
export const PAGE_SIZES=[10,25,50] as const;
export type PageSize=(typeof PAGE_SIZES)[number];
export function PageSizeSelect({value,onChange}:{value:PageSize;onChange:(size:PageSize)=>void}){return <label>Wierszy na stronę<select value={value} onChange={event=>{const parsed=Number(event.currentTarget.value);const next=PAGE_SIZES.find(size=>size===parsed);if(next!==undefined)onChange(next);}}>{PAGE_SIZES.map(size=><option key={size} value={size}>{size}</option>)}</select></label>;}
export function RangeInfo({from,to,total}:{from:number;to:number;total:number}){return <p aria-live="polite">{total===0?"Brak wyników":`Wiersze ${from}–${to} z ${total}`}</p>;}
export function Main({tickets}:{tickets:readonly Ticket[]}){const [query,setQuery]=useState("");const [status,setStatus]=useState<"ALL"|Ticket["status"]>("ALL");const [sort,setSort]=useState<SortState>({key:"createdAt",direction:"desc"});const [page,setPage]=useState(1);const [pageSize,setPageSize]=useState<PageSize>(10);const filtered=tickets.filter(ticket=>(status==="ALL"||ticket.status===status)&&ticket.title.toLowerCase().includes(query.trim().toLowerCase()));const sorted=sortTickets(filtered,sort);const result=paginate(sorted,page,pageSize);const statuses=["ALL","OPEN","IN_PROGRESS","CLOSED"] as const;const columns=[{key:"id",label:"Id"},{key:"title",label:"Tytuł"},{key:"priority",label:"Priorytet"},{key:"createdAt",label:"Utworzono"}] as const;return <main><label>Szukaj w tytule<input value={query} onChange={event=>{setQuery(event.currentTarget.value);setPage(1);}}/></label><label>Status<select value={status} onChange={event=>{const raw=event.currentTarget.value;const next=statuses.find(value=>value===raw);if(next!==undefined){setStatus(next);setPage(1);}}}>{statuses.map(value=><option key={value} value={value}>{value}</option>)}</select></label><PageSizeSelect value={pageSize} onChange={next=>{setPageSize(next);setPage(1);}}/><RangeInfo from={result.from} to={result.to} total={filtered.length}/><table><thead><tr>{columns.map(column=><SortHeader key={column.key} label={column.label} column={column.key} sort={sort} onSort={key=>{setSort(current=>nextSort(current,key));setPage(1);}}/>)}</tr></thead><tbody>{result.pageItems.length===0?<tr><td colSpan={4}>Brak wyników</td></tr>:result.pageItems.map(ticket=><tr key={ticket.id}><td>{ticket.id}</td><td>{ticket.title}</td><td>{ticket.priority}</td><td>{ticket.createdAt}</td></tr>)}</tbody></table><Pager page={result.currentPage} pageCount={result.pageCount} onPageChange={setPage}/></main>;}

